define(["core/ajax","core/notification"],function(Ajax,Notification){const init=function(bookflowId){document.addEventListener("click",function(event){const button=event.target.closest("[data-action='bookflow-bookmark']");if(!button){return}const bookmarked=button.getAttribute("aria-pressed")==="true";const request=bookmarked?{methodname:"mod_bookflow_delete_bookmark",args:{bookflowid:bookflowId,bookmarkid:Number(button.dataset.bookmarkId)}}:{methodname:"mod_bookflow_create_bookmark",args:{bookflowid:bookflowId,itemtype:button.dataset.itemType,chapterid:Number(button.dataset.chapterId||0),contentid:Number(button.dataset.contentId||0)}};button.disabled=true;Ajax.call([request])[0].then(function(){window.location.reload();return true}).catch(function(error){button.disabled=false;Notification.exception(error)})})};return{init:init}});